INSERT INTO "guide_settings" ("id", "steps", "updated_at") VALUES (1, '[{"id":"move","title":"先动起来","desc":"拖住左下角的摇杆走两步；电脑上也可以按住方向键或点地面。","spot":"joystick","trigger":"move"},{"id":"fight","title":"打一只怪","desc":"走近怪物，点下面的技能（或按 1~6）就能出手。","spot":"shortcut","trigger":"kill"},{"id":"loot","title":"把掉落捡起来","desc":"怪死了会掉东西，走上去就会自动拾取，东西直接进背包。","spot":"nav:bag","trigger":"pickup"},{"id":"bag","title":"看看背包","desc":"刚捡的装备和药都在这里：点格子看详情，装备可以直接穿上。","spot":"nav:bag","trigger":"openBag"},{"id":"skill","title":"认识你的技能","desc":"技能列表里有全部技能和解锁等级，拖到快捷栏就能随时用。","spot":"nav:skill","trigger":"openSkill"},{"id":"social","title":"别一个人玩","desc":"聊天分世界 / 帮会 / 私聊三页；任务在左边的追踪栏，点一下就能打开任务面板。","spot":"nav:chat","trigger":"openChat"}]', 0);
